command:
exec > /out/cg-priv3.txt 2>&1; echo '== nsroot =='; cat /proc/self/cgroup; echo '-- controllers:'; cat /sys/fs/cgroup/cgroup.controllers; echo '-- subtree_control now:'; cat /sys/fs/cgroup/cgroup.subtree_control; echo; echo '== create + inspect =='; mkdir /sys/fs/cgroup/s1; cat /sys/fs/cgroup/s1/cgroup.controllers; ls /sys/fs/cgroup/s1/ | head -20; echo; echo '== enable single pids =='; (echo '+pids' > /sys/fs/cgroup/s1/cgroup.subtree_control) 2>&1; echo "rc=$?"; echo '-- after:'; cat /sys/fs/cgroup/s1/cgroup.subtree_control; echo; echo '== enable cpu =='; (echo '+cpu' > /sys/fs/cgroup/s1/cgroup.subtree_control) 2>&1; echo "rc=$?"; cat /sys/fs/cgroup/s1/cgroup.subtree_control; echo; echo '== memory.max direct =='; (echo 100000000 > /sys/fs/cgroup/s1/memory.max) 2>&1; echo "rc=$?"; echo; echo '== python errno probe =='; python3 - <<'EOP'
for fn, data in [('cgroup.subtree_control','+cpu +memory'), ('memory.max','100000000'), ('pids.max','10')]:
    try:
        open('/sys/fs/cgroup/s1/'+fn,'w').write(data); print(fn, '-> OK')
    except OSError as e:
        print(fn, '->', type(e).__name__, e.errno, e.strerror)
EOP
echo; rmdir /sys/fs/cgroup/s1 2>&1; echo done
